using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ChangeDiceActionForOneTurnCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/ChangeDiceActionForOneTurnCustomDescription", order = 0)]
public class ChangeDiceActionForOneTurnCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		ChangeDiceActionForOneTurnAction changeDiceActionForOneTurnAction = battleAction as ChangeDiceActionForOneTurnAction;
		string actionName = changeDiceActionForOneTurnAction.ActionToChange.GetActionName();
		string text = "";
		if (changeDiceActionForOneTurnAction.EnableExtraBattleAction)
		{
			text = "\n" + Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedIfYouDo(), changeDiceActionForOneTurnAction.ExtraBattleAction.GetActionDescription(changeDiceActionForOneTurnAction.ExtraActionValue).LowercaseFirst());
		}
		string text2 = "";
		if (changeDiceActionForOneTurnAction.NotAffectedByDoom)
		{
			text2 = "\n" + base.localizationManager.GetLocalizedString("IgnoreDoom");
		}
		return Smart.Format(base.localizationManager.GetLocalizedString("ChangeEnemyDieFace"), actionName, GetAmountWithUnlockablesModification(amountModified)) + text2 + text;
	}
}
